#include <Eigen/Dense>
#include <cmath>
#include <cstdint>

extern "C" int dom_eig(const double* Ain, int n, double* lam, double* vec) {
    if (n < 1 || n > 10) return -4;
    typedef Eigen::Matrix<double, Eigen::Dynamic, Eigen::Dynamic, 0, 10, 10> Mat;
    Mat A(n, n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            A(i, j) = Ain[i * n + j];

    Eigen::EigenSolver<Mat> es(A, true);
    if (es.info() != Eigen::Success) return 1;
    auto ev = es.eigenvalues();
    auto V = es.eigenvectors();

    int best = 0;
    double bestmag = std::norm(ev(0));
    for (int i = 1; i < n; ++i) {
        double m = std::norm(ev(i));
        if (m > bestmag) { bestmag = m; best = i; }
    }
    lam[0] = ev(best).real();
    lam[1] = ev(best).imag();
    double ss = 0.0;
    for (int k = 0; k < n; ++k) {
        vec[2 * k] = V(k, best).real();
        vec[2 * k + 1] = V(k, best).imag();
        ss += std::norm(V(k, best));
    }
    double inv = 1.0 / std::sqrt(ss);
    for (int k = 0; k < 2 * n; ++k) vec[k] *= inv;
    return 0;
}
