#include <stdint.h>
#include <stddef.h>
#include <string.h>
#include <dlfcn.h>
#include <math.h>
#include <complex.h>

#define MAXN 64

typedef void (*dgeev_fn)(char*, char*, int64_t*, double*, int64_t*, double*,
                         double*, double*, int64_t*, double*, int64_t*,
                         double*, int64_t*, int64_t*, size_t, size_t);

static dgeev_fn geev_ptr = 0;

int dom_init(const char *libpath) {
    void *h = dlopen(libpath, RTLD_NOW | RTLD_GLOBAL);
    if (!h) return -2;
    const char *names[] = {"scipy_dgeev_64_", "dgeev_64_", "scipy_dgeev_", "dgeev_", 0};
    for (int i = 0; names[i]; ++i) {
        void *p = dlsym(h, names[i]);
        if (p) { geev_ptr = (dgeev_fn)p; return 0; }
    }
    return -3;
}

static int lu_solve(int n, double complex *M, double complex *b) {
    for (int k = 0; k < n; ++k) {
        int p = k;
        double best = cabs(M[k * n + k]);
        for (int i = k + 1; i < n; ++i) {
            double v = cabs(M[i * n + k]);
            if (v > best) { best = v; p = i; }
        }
        if (best < 1e-300) return 1;
        if (p != k) {
            for (int j = k; j < n; ++j) {
                double complex t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            double complex t = b[k]; b[k] = b[p]; b[p] = t;
        }
        double complex piv = M[k * n + k];
        for (int i = k + 1; i < n; ++i) {
            double complex f = M[i * n + k] / piv;
            if (f == 0.0) continue;
            M[i * n + k] = 0.0;
            for (int j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        double complex s = b[i];
        for (int j = i + 1; j < n; ++j) s -= M[i * n + j] * b[j];
        b[i] = s / M[i * n + i];
    }
    return 0;
}

static void get_eigenvalues(const double *Ain, int n, double *wr, double *wi, int *status) {
    double a[MAXN * MAXN];
    double work[32 * MAXN], vl[1];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            a[j * n + i] = Ain[i * n + j];
    char jobvl = 'N', jobvr = 'N';
    int64_t N = n, lda = n, ldvl = 1, ldvr = 1;
    int64_t lwork = 32 * n, info = 0;
    geev_ptr(&jobvl, &jobvr, &N, a, &lda, wr, wi, vl, &ldvl, vl, &ldvr,
             work, &lwork, &info, (size_t)1, (size_t)1);
    *status = (int)info;
}

/* full LAPACK eigenpairs, used as fallback */
static int full_eig(const double *Ain, int n, double *lam, double *vec) {
    double a[MAXN * MAXN], vr[MAXN * MAXN];
    double wr[MAXN], wi[MAXN], work[32 * MAXN], vl[1];
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j)
            a[j * n + i] = Ain[i * n + j];
    char jobvl = 'N', jobvr = 'V';
    int64_t N = n, lda = n, ldvl = 1, ldvr = n;
    int64_t lwork = 32 * n, info = 0;
    geev_ptr(&jobvl, &jobvr, &N, a, &lda, wr, wi, vl, &ldvl, vr, &ldvr,
             work, &lwork, &info, (size_t)1, (size_t)1);
    if (info != 0) return info > 0 ? 1 : 2;
    int best = 0;
    double bestmag = wr[0] * wr[0] + wi[0] * wi[0];
    for (int i = 1; i < n; ++i) {
        double m = wr[i] * wr[i] + wi[i] * wi[i];
        if (m > bestmag) { bestmag = m; best = i; }
    }
    int i = best;
    if (wi[i] < 0.0) --i;
    lam[0] = wr[i]; lam[1] = wi[i];
    if (wi[i] == 0.0) {
        for (int k = 0; k < n; ++k) { vec[2*k] = vr[k + i*n]; vec[2*k+1] = 0.0; }
    } else {
        for (int k = 0; k < n; ++k) { vec[2*k] = vr[k + i*n]; vec[2*k+1] = vr[k + (i+1)*n]; }
    }
    double ss = 0.0;
    for (int k = 0; k < n; ++k) ss += vec[2*k]*vec[2*k] + vec[2*k+1]*vec[2*k+1];
    double inv = 1.0 / sqrt(ss);
    for (int k = 0; k < 2*n; ++k) vec[k] *= inv;
    return 0;
}

int dom_eig(const double *Ain, int n, double *lam, double *vec) {
    if (!geev_ptr) return -1;
    if (n < 1 || n > MAXN) return -4;

    double wr[MAXN], wi[MAXN];
    int st = 0;
    get_eigenvalues(Ain, n, wr, wi, &st);
    if (st != 0) return full_eig(Ain, n, lam, vec);

    int best = 0;
    double bestmag = wr[0]*wr[0] + wi[0]*wi[0];
    for (int i = 1; i < n; ++i) {
        double m = wr[i]*wr[i] + wi[i]*wi[i];
        if (m > bestmag) { bestmag = m; best = i; }
    }
    double complex mu = wr[best] + I*wi[best];

    double scale = 0.0;
    for (int i = 0; i < n*n; ++i) scale += Ain[i]*Ain[i];
    scale = sqrt(scale);

    double complex M[MAXN * MAXN], b[MAXN], y[MAXN], Ay[MAXN];
    double c = 1e-10;
    int ok = 0;

    if (scale == 0.0) {
        lam[0] = wr[best]; lam[1] = wi[best];
        for (int k = 0; k < n; ++k) { vec[2*k] = (k == 0); vec[2*k+1] = 0.0; }
        return 0;
    }

    for (int it = 0; it < 2; ++it) {
        double complex shift = mu + (c * scale);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) M[i*n+j] = (double complex)Ain[i*n+j];
            M[i*n+i] -= shift;
            b[i] = (it == 0) ? (double complex)(i + 1) : y[i];
        }
        if (lu_solve(n, M, b)) { return full_eig(Ain, n, lam, vec); }
        double ss = 0.0;
        for (int i = 0; i < n; ++i) ss += creal(b[i])*creal(b[i]) + cimag(b[i])*cimag(b[i]);
        if (!(ss > 0.0) || !isfinite(ss)) { return full_eig(Ain, n, lam, vec); }
        double inv = 1.0 / sqrt(ss);
        for (int i = 0; i < n; ++i) y[i] = b[i] * inv;

        /* Rayleigh quotient and residual */
        double complex num = 0.0, den = 0.0;
        for (int i = 0; i < n; ++i) {
            double complex s = 0.0;
            for (int j = 0; j < n; ++j) s += Ain[i*n+j] * y[j];
            Ay[i] = s;
            num += conj(y[i]) * s;
            den += conj(y[i]) * y[i];
        }
        if (!(cabs(den) > 0.0)) { return full_eig(Ain, n, lam, vec); }
        mu = num / den;

        double rn = 0.0, vn = 0.0;
        for (int i = 0; i < n; ++i) {
            double complex r = Ay[i] - mu * y[i];
            rn += creal(r)*creal(r) + cimag(r)*cimag(r);
            vn += creal(y[i])*creal(y[i]) + cimag(y[i])*cimag(y[i]);
        }
        if (sqrt(rn) <= 1e-9 * sqrt(vn)) ok = 1;
        else ok = 0;
        if (ok && it == 1) {
            lam[0] = creal(mu); lam[1] = cimag(mu);
            for (int k = 0; k < n; ++k) { vec[2*k] = creal(y[k]); vec[2*k+1] = cimag(y[k]); }
            return 0;
        }
    }
    return full_eig(Ain, n, lam, vec);
}
