#include <stddef.h>
#include <math.h>
#include <complex.h>

#define MAXN 64

static int lu_solve(int n, double complex *M, double complex *b) {
    for (int k = 0; k < n; ++k) {
        int p = k;
        double best = cabs(M[k * n + k]);
        for (int i = k + 1; i < n; ++i) {
            double v = cabs(M[i * n + k]);
            if (v > best) { best = v; p = i; }
        }
        if (!(best > 1e-300)) return 1;
        if (p != k) {
            for (int j = k; j < n; ++j) {
                double complex t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            double complex t = b[k]; b[k] = b[p]; b[p] = t;
        }
        double complex piv = M[k * n + k];
        for (int i = k + 1; i < n; ++i) {
            double complex f = M[i * n + k] / piv;
            if (f == 0.0) continue;
            M[i * n + k] = 0.0;
            for (int j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        double complex s = b[i];
        for (int j = i + 1; j < n; ++j) s -= M[i * n + j] * b[j];
        b[i] = s / M[i * n + i];
    }
    return 0;
}

/* A is row-major n*n. lam_in is an approximate dominant eigenvalue.
   On success writes lam_out (re,im) and vec_out (interleaved re,im). */
int eig_from_shift(const double *Ain, int n, double lam_re, double lam_im,
                   double *lam_out, double *vec_out) {
    if (n < 1 || n > MAXN) return -4;

    double scale = 0.0;
    for (int i = 0; i < n * n; ++i) scale += Ain[i] * Ain[i];
    scale = sqrt(scale);

    double complex mu = lam_re + I * lam_im;
    if (scale == 0.0) {
        lam_out[0] = lam_re; lam_out[1] = lam_im;
        for (int k = 0; k < n; ++k) { vec_out[2*k] = (k == 0); vec_out[2*k+1] = 0.0; }
        return 0;
    }

    double complex M[MAXN * MAXN], b[MAXN], y[MAXN], Ay[MAXN];
    const double c = 1e-10;

    for (int it = 0; it < 2; ++it) {
        double complex shift = mu + (c * scale);
        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < n; ++j) M[i*n+j] = (double complex)Ain[i*n+j];
            M[i*n+i] -= shift;
            b[i] = (it == 0) ? (double complex)(i + 1) : y[i];
        }
        if (lu_solve(n, M, b)) return 1;

        double ss = 0.0;
        for (int i = 0; i < n; ++i)
            ss += creal(b[i])*creal(b[i]) + cimag(b[i])*cimag(b[i]);
        if (!(ss > 0.0) || !isfinite(ss)) return 2;
        double inv = 1.0 / sqrt(ss);
