static int lu_solve(int n, double complex *M, double complex *b) {
    for (int k = 0; k < n; ++k) {
        int p = k;
        double best = cabs(M[k * n + k]);
        for (int i = k + 1; i < n; ++i) {
            double v = cabs(M[i * n + k]);
            if (v > best) { best = v; p = i; }
        }
        if (!(best > 1e-300)) return 1;
        if (p != k) {
            for (int j = k; j < n; ++j) {
                double complex t = M[k * n + j];
                M[k * n + j] = M[p * n + j];
                M[p * n + j] = t;
            }
            double complex t = b[k]; b[k] = b[p]; b[p] = t;
        }
        double complex piv = M[k * n + k];
        for (int i = k + 1; i < n; ++i) {
            double complex f = M[i * n + k] / piv;
            if (f == 0.0) continue;
            M[i * n + k] = 0.0;
            for (int j = k + 1; j < n; ++j)
                M[i * n + j] -= f * M[k * n + j];
            b[i] -= f * b[k];
        }
    }
    for (int i = n - 1; i >= 0; --i) {
        double complex s = b[i];
        for (int j = i + 1; j < n; ++j) s -= M[i * n + j] * b[j];
        b[i] = s / M[i * n + i];
    }
    return 0;
}

