            double complex r = Ay[i] - mu * y[i];
            rn += creal(r)*creal(r) + cimag(r)*cimag(r);
            vn += creal(y[i])*creal(y[i]) + cimag(y[i])*cimag(y[i]);
        }
        if (!isfinite(rn) || !isfinite(vn)) return 4;
        if (it == 1) {
